package com.sqlcompat.core.rule.builtin;

import com.sqlcompat.core.model.Issue;
import com.sqlcompat.core.model.Severity;
import com.sqlcompat.core.rule.DialectRule;
import com.sqlcompat.core.rule.RuleContext;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * R007 - MySQL {@code AUTO_INCREMENT}.
 *
 * <p>Kingbase / PostgreSQL use identity columns
 * ({@code GENERATED BY DEFAULT AS IDENTITY}) or explicit sequences. Migrating also means the
 * sequence must be positioned after existing data — a table-level concern this rule can only
 * point at, not fix.
 */
public final class AutoIncrementRule implements DialectRule {

    private static final Pattern PATTERN = Pattern.compile(
            "\\bauto_increment\\b", Pattern.CASE_INSENSITIVE);

    @Override
    public String id() {
        return "R007";
    }

    @Override
    public String name() {
        return "AUTO_INCREMENT must become an identity column or sequence";
    }

    @Override
    public Severity defaultSeverity() {
        return Severity.BLOCKER;
    }

    @Override
    public String description() {
        return "AUTO_INCREMENT is MySQL-only DDL syntax.";
    }

    @Override
    public String suggestion() {
        return "id BIGINT AUTO_INCREMENT -> id BIGINT GENERATED BY DEFAULT AS IDENTITY  "
                + "(or a SEQUENCE with nextval)";
    }

    @Override
    public List<Issue> check(RuleContext context) {
        String sql = context.sql();
        Matcher matcher = PATTERN.matcher(sql);
        List<Issue> issues = new ArrayList<>();
        while (matcher.find()) {
            String message = context.lowerCaseSql().contains("create table")
                    ? "AUTO_INCREMENT is MySQL-only DDL; the sequence must also be repositioned "
                      + "past existing ids after data migration."
                    : "AUTO_INCREMENT is MySQL-only syntax.";
            issues.add(new Issue(
                    id(),
                    name(),
                    defaultSeverity(),
                    message,
                    "AUTO_INCREMENT",
                    suggestion(),
                    context.location()));
        }
        return issues;
    }
}
